"""Errors."""

from __future__ import annotations


class ProcessCallFailedError(RuntimeError):
    """Failed a process call."""

    def __init__(self, code: int, out: str, err: str, cmd: list[str]) -> None:
        super().__init__(code, out, err, cmd)
        self.code = code
        self.out = out
        self.err = err
        self.cmd = cmd
